// Builds supabase/deploy/g1_bundle.sql: every migration in supabase/migrations
// in one all-or-nothing transaction, plus the same migration-history rows the
// Supabase CLI writes, so it can be pasted once into the Supabase SQL editor
// (e.g. from a phone). Refuses to run if Trip Prep is already deployed.
//
//   node scripts/build-supabase-bundle.mjs           # write the bundle
//   node scripts/build-supabase-bundle.mjs --check   # fail if it is out of date

import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const root = join(import.meta.dirname, '..');
const dir = join(root, 'supabase', 'migrations');
const out = join(root, 'supabase', 'deploy', 'g1_bundle.sql');
export const G1_FILES = ['20261111090000_trip_prep_schema.sql', '20261111090100_trip_prep_sync_functions.sql'];

export function buildBundle() {
  // Only the G1 migrations: this bundle is the one-time setup for an empty project. Later
  // migrations are deployed with the GitHub workflow (supabase db push), never by bundle.
  const files = readdirSync(dir).filter((f) => f.endsWith('.sql') && G1_FILES.includes(f)).sort();
  const parts = files.map((file) => {
    const [version, ...rest] = file.replace(/\.sql$/, '').split('_');
    return { file, version, name: rest.join('_'), sql: readFileSync(join(dir, file), 'utf8').trimEnd() };
  });
  return [
    '-- GENERATED by scripts/build-supabase-bundle.mjs from supabase/migrations. Do not edit.',
    '-- Paste the whole file into Supabase → SQL Editor → Run, once. It applies every',
    '-- migration in one transaction (all or nothing) and records them in the migration',
    '-- history like `supabase db push`. If Trip Prep is already deployed it stops and changes nothing.',
    '',
    'begin;',
    '',
    'do $guard$',
    'begin',
    "  if to_regclass('public.trips') is not null or to_regclass('public.sync_tables') is not null then",
    "    raise exception 'Trip Prep schema is already deployed. Nothing was changed.';",
    '  end if;',
    'end',
    '$guard$;',
    '',
    ...parts.flatMap((p) => [`-- ===== ${p.file} =====`, p.sql, '']),
    '-- ===== migration history (same table the Supabase CLI uses) =====',
    'create schema if not exists supabase_migrations;',
    'create table if not exists supabase_migrations.schema_migrations (version text not null primary key, statements text[], name text);',
    ...parts.map(
      (p) => `insert into supabase_migrations.schema_migrations (version, name) values ('${p.version}', '${p.name}');`,
    ),
    '',
    'commit;',
    '',
  ].join('\n');
}

if (process.argv[1] && import.meta.filename === process.argv[1]) {
  const bundle = buildBundle();
  if (process.argv.includes('--check')) {
    if (readFileSync(out, 'utf8') !== bundle) {
      console.error('supabase/deploy/g1_bundle.sql is out of date. Run: node scripts/build-supabase-bundle.mjs');
      process.exit(1);
    }
    console.log('Bundle is up to date.');
  } else {
    writeFileSync(out, bundle);
    console.log(`Wrote ${out}`);
  }
}
